import app from 'flarum/admin/app';
import FormModal from 'flarum/common/components/FormModal';
import Button from 'flarum/common/components/Button';
const t = (key, params) => app.translator.trans('mrcaspan-flarum2-mail-catcher.admin.' + key, params);

/**
 * Explains Forward mode and asks for the address all email goes to.
 * attrs: forwardTo (last used address), onconfirm(address)
 */
export default class ForwardModeModal extends FormModal {
  oninit(vnode) {
    super.oninit(vnode);
    this.to = this.attrs.forwardTo || '';
  }
  className() {
    return 'MailCatcher-forwardModal Modal--small';
  }
  title() {
    return t('forward_modal_title');
  }
  content() {
    return m("div", {
      className: "Modal-body"
    }, m("p", null, t('forward_modal_text')), m("p", null, t('forward_modal_settings')), m("p", null, m("b", null, t('forward_modal_warning'))), m("div", {
      className: "Form-group"
    }, m("label", null, t('forward_modal_to_label')), m("input", {
      className: "FormControl",
      type: "email",
      name: "to",
      required: true,
      placeholder: t('release_other_placeholder'),
      value: this.to,
      oninput: e => this.to = e.target.value
    })), m("div", {
      className: "MailCatcher-modalButtons"
    }, m(Button, {
      className: "Button Button--primary",
      type: "submit",
      icon: "fas fa-share"
    }, t('forward_modal_confirm'))));
  }
  onsubmit(e) {
    e.preventDefault();
    const to = this.to.trim();
    if (!to) return;
    this.hide();
    this.attrs.onconfirm(to);
  }
}
flarum.reg.add('mrcaspan-flarum2-mail-catcher', 'admin/components/ForwardModeModal', ForwardModeModal);